import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPlayfair = makeLoadFont('PlayfairDisplay');
const loadInter = makeLoadFont('Inter');

// Module-level font loading
const { fontFamily: playfairFamily } = loadPlayfair();
const { fontFamily: interFamily } = loadInter();



export type MindfulEatingProps = Record<string, any>;

const MindfulEating: React.FC<MindfulEatingProps> = ({
  backgroundColor = "#F4F1EA",
  transparentBackground = false,
  durationInSeconds = 6,
  title = "Mindful Eating",
  titleColor = "#2C3E50",
  cardColor = "#FFFFFF",
  textColor = "#2C3E50",
  rules = [
    { emoji: "🐢", text: "Eat slowly" },
    { emoji: "👁️", text: "Eat mindfully" },
    { emoji: "✅", text: "Stop at satisfied" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Title Animation (Slides down and fades in)
  const titleProgress = spring({
    frame,
    fps,
    config: { damping: 14, mass: 1 },
  });

  const titleY = interpolate(titleProgress, [0, 1], [-50, 0]);
  const titleOpacity = interpolate(titleProgress, [0, 1], [0, 1]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        display: "flex",
        flexDirection: "column",
        justifyContent: "center",
        alignItems: "center",
        fontFamily: interFamily,
      }}
    >
      <div
        style={{
          width: width * 0.85,
          display: "flex",
          flexDirection: "column",
          gap: "60px",
          marginTop: height * 0.05,
        }}
      >
        {/* Title */}
        <h1
          style={{
            fontFamily: playfairFamily,
            fontSize: "80px",
            color: titleColor,
            textAlign: "center",
            margin: 0,
            opacity: titleOpacity,
            transform: `translateY(${titleY}px)`,
            transition: "none",
          }}
        >
          {title}
        </h1>

        {/* Stacked Rules */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            gap: "40px",
            width: "100%",
          }}
        >
          {rules.map((rule, index) => {
            // Staggered entrance based on index
            const delay = 15 + index * 12;

            const cardProgress = spring({
              frame: frame - delay,
              fps,
              config: { damping: 12, mass: 0.8, stiffness: 100 },
            });

            // Card slides up, scales slightly, and fades in
            const cardY = interpolate(cardProgress, [0, 1], [150, 0]);
            const cardScale = interpolate(cardProgress, [0, 1], [0.9, 1]);
            const cardOpacity = interpolate(cardProgress, [0, 1], [0, 1]);

            // Inner content stagger
            const contentProgress = spring({
              frame: frame - (delay + 8),
              fps,
              config: { damping: 15 },
            });
            const contentX = interpolate(contentProgress, [0, 1], [-30, 0]);
            const contentOpacity = interpolate(contentProgress, [0, 1], [0, 1]);

            return (
              <div
                key={index}
                style={{
                  backgroundColor: cardColor,
                  borderRadius: "32px",
                  padding: "50px 60px",
                  display: "flex",
                  alignItems: "center",
                  gap: "40px",
                  boxShadow: "0 20px 40px rgba(0,0,0,0.05)",
                  opacity: cardOpacity,
                  transform: `translateY(${cardY}px) scale(${cardScale})`,
                  transition: "none",
                }}
              >
                <div
                  style={{
                    fontSize: "100px",
                    lineHeight: 1,
                    opacity: contentOpacity,
                    transform: `translateX(${contentX}px)`,
                    transition: "none",
                  }}
                >
                  {rule.emoji}
                </div>
                <div
                  style={{
                    fontSize: "64px",
                    fontWeight: 600,
                    color: textColor,
                    letterSpacing: "-0.02em",
                    opacity: contentOpacity,
                    transform: `translateX(${contentX}px)`,
                    transition: "none",
                  }}
                >
                  {rule.text}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MindfulEating;